package com.tacz.guns.api;import java.util.*;import net.minecraft.resources.ResourceLocation;public class TimelessAPI{public static boolean missing;public static Optional<Object>getCommonGunIndex(ResourceLocation r){return missing?Optional.empty():Optional.of(new Index());}public static List<Map.Entry<ResourceLocation,Index>>getAllCommonGunIndex(){return List.of(Map.entry(ResourceLocation.parse("alternate:pistol"),new Index()));}public static class Index{public String getType(){return "pistol";}public Data getGunData(){return new Data();}}public static class Data{public Bullet getBulletData(){return new Bullet();}}public static class Bullet{public float getDamageAmount(){return 5;}public Extra getExtraDamage(){return new Extra();}}public static class Extra{public float getHeadShotMultiplier(){return 2;}}}